from duckduckgo_search import DDGS
import time

time.sleep(5)

# Try suggestions/specific terms
with DDGS() as ddgs:
    try:
        suggestions = list(ddgs.suggestions('medical tourism'))
        print("Suggestions for 'medical tourism':")
        for s in suggestions:
            print(f"  - {s['phrase']}")
    except Exception as e:
        print(f"Suggestions error: {e}")

time.sleep(2)

with DDGS() as ddgs:
    try:
        suggestions = list(ddgs.suggestions('healthcare tourism'))
        print("\nSuggestions for 'healthcare tourism':")
        for s in suggestions:
            print(f"  - {s['phrase']}")
    except Exception as e:
        print(f"Suggestions error: {e}")

time.sleep(2)

with DDGS() as ddgs:
    try:
        suggestions = list(ddgs.suggestions('China health tourism'))
        print("\nSuggestions for 'China health tourism':")
        for s in suggestions:
            print(f"  - {s['phrase']}")
    except Exception as e:
        print(f"Suggestions error: {e}")
